import {createSaveStore,decodeSave,SAVE_KEY,BACKUP_KEY} from './save.mjs';
export async function openSaveDatabase(factory=globalThis.indexedDB){
 if(!factory)return null;
 return new Promise((resolve,reject)=>{const r=factory.open('portmann-alp-saves',1);r.onupgradeneeded=()=>r.result.createObjectStore('saves');r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Speicherdatenbank durch anderen Tab blockiert.'));r.onsuccess=()=>{const db=r.result;db.onversionchange=()=>db.close();resolve({read(key){return new Promise((ok,no)=>{const t=db.transaction('saves'),q=t.objectStore('saves').get(key);q.onsuccess=()=>ok(q.result??null);q.onerror=()=>no(q.error);});},write(key,raw,expected){return new Promise((ok,no)=>{const t=db.transaction('saves','readwrite'),s=t.objectStore('saves'),q=s.get(key);q.onsuccess=()=>{const current=decodeSave(q.result);if(expected!==undefined&&(current?.revision??-1)!==expected){t.abort();return;}if(current)s.put(q.result,key+'-backup');s.put(raw,key);};t.oncomplete=()=>ok();t.onabort=t.onerror=()=>no(t.error||Error('Speichertransaktion fehlgeschlagen.'));});}});};});
}
export async function createDurableSaveStore(storage,{namespace='',database,onStatus=()=>{}}={}){
 const key=SAVE_KEY+namespace,backup=key+'-backup',cache=new Map();let localOK=true,db=database,queue=Promise.resolve(),secondaryError='',lastPersisted=0,dbRevision=-1,dbConflict=false;
 for(const k of[key,backup])try{cache.set(k,storage.getItem(k));}catch{localOK=false;cache.set(k,null);}
 if(db===undefined)try{db=await openSaveDatabase();}catch{db=null;secondaryError='Zweite Speicherablage nicht verfügbar.';}
 let primary=decodeSave(cache.get(key));
 if(db)try{const raw=await db.read(key),braw=await db.read(backup),other=decodeSave(raw)||decodeSave(braw);dbRevision=decodeSave(raw)?.revision??-1;if(other&&(!primary||other.revision>primary.revision||(other.revision===primary.revision&&other.savedAt>primary.savedAt))){cache.set(key,JSON.stringify(other));primary=other;try{storage.setItem(key,cache.get(key));}catch{localOK=false;}}}catch{secondaryError='Zweite Speicherablage konnte nicht gelesen werden.';}
 const adapter={getItem(k){const actual=k===SAVE_KEY?key:backup;if(localOK){try{return storage.getItem(actual);}catch{localOK=false;}}return cache.get(actual)??null;},setItem(k,v){const actual=k===SAVE_KEY?key:backup;if(localOK){try{storage.setItem(actual,v);}catch(e){localOK=false;if(!db)throw e;}}else if(!db)throw Error('Kein Gerätespeicher verfügbar');cache.set(actual,v);}};
 const base=createSaveStore(adapter);let result=base.load();
 function persist(raw){if(!db)return;queue=queue.catch(()=>{}).then(()=>db.write(key,raw,dbRevision)).then(()=>{dbRevision=decodeSave(raw)?.revision??-1;lastPersisted=decodeSave(raw)?.savedAt||0;secondaryError='';onStatus();},()=>{dbConflict=true;secondaryError='IndexedDB-Sicherung fehlgeschlagen oder parallel geändert. Seite neu laden oder Spielstanddatei sichern.';onStatus();});}
 if(primary&&db)persist(JSON.stringify(primary));
 return{load:()=>result,get status(){const s=base.status;return{...s,ok:!dbConflict&&s.ok&&(localOK||lastPersisted===s.lastSavedAt&&lastPersisted>0),message:!s.ok?s.message:!localOK?(secondaryError||(lastPersisted===s.lastSavedAt&&lastPersisted>0?'In IndexedDB auf diesem Gerät gespeichert.':'IndexedDB-Sicherung wird geschrieben; Seite noch offen lassen.')):secondaryError||s.message,secondaryError};},write(state,options){if(dbConflict&&!options?.allowReplace)return{ok:false,message:secondaryError};const r=base.write(state,options);if(r.ok){result=state;persist(JSON.stringify(state));}return{...r,ok:r.ok&&localOK,message:!localOK?(db?'Gerätesicherung wird geschrieben.':'Gerätespeicher nicht verfügbar.'):r.message};},export:base.export,flush:()=>queue};
}
